messages.content:
Generate a standalone C reproducer that triggers this vulnerability:

File: bfd/coff-aarch64.c
Line: 520
Function: coff_pe_aarch64_relocate_section
Bug type: out-of-bounds-read
CWE: CWE-125
Explanation: rel->r_symndx is used to index syms[symndx] (line 520), obj_coff_sym_hashes(input_bfd)[symndx] (line 522), and sections[symndx] (line 531) before validating symndx. The bounds check occurs later at lines 545–547. A malformed object with an invalid r_symndx can cause out-of-bounds reads and potentially invalid pointer dereferences.

Source context:
```c
      480: 
      481: static bool
      482: coff_pe_aarch64_relocate_section (bfd *output_bfd,
      483: 				  struct bfd_link_info *info,
      484: 				  bfd *input_bfd,
      485: 				  asection *input_section,
      486: 				  bfd_byte *contents,
      487: 				  struct internal_reloc *relocs,
      488: 				  struct internal_syment *syms,
      489: 				  asection **sections)
      490: {
      491:   struct internal_reloc *rel;
      492:   struct internal_reloc *relend;
      493: 
      494:   if (bfd_link_relocatable (info))
      495:     return true;
      496: 
      497:   rel = relocs;
      498:   relend = rel + input_section->reloc_count;
      499: 
      500:   /* The addend for a relocation is stored in the immediate bits of each
      501:      opcode.  So for each relocation, we need to extract the immediate value,
      502:      use this to calculate what it should be for the symbol, and rewrite the
      503:      opcode into the section stream.  */
      504: 
      505:   for (; rel < relend; rel++)
      506:     {
      507:       long symndx;
      508:       struct coff_link_hash_entry *h;
      509:       bfd_vma sym_value;
      510:       asection *sec = NULL;
      511:       uint64_t dest_vma;
      512: 
      513:       /* skip trivial relocations */
      514:       if (rel->r_type == IMAGE_REL_ARM64_ADDR32
      515: 	  || rel->r_type == IMAGE_REL_ARM64_ADDR64
      516: 	  || rel->r_type == IMAGE_REL_ARM64_ABSOLUTE)
      517: 	continue;
      518: 
      519:       symndx = rel->r_symndx;
>>>   520:       sym_value = syms[symndx].n_value;
      521: 
      522:       h = obj_coff_sym_hashes (input_bfd)[symndx];
      523: 
      524:       if (h && h->root.type == bfd_link_hash_defined)
      525: 	{
      526: 	  sec = h->root.u.def.section;
      527: 	  sym_value = h->root.u.def.value;
      528: 	}
      529:       else
      530: 	{
      531: 	  sec = sections[symndx];
      532: 	}
      533: 
      534:       if (!sec)
      535: 	continue;
      536: 
      537:       if (bfd_is_und_section (sec))
      538: 	continue;
      539: 
      540:       if (discarded_section (sec))
      541: 	continue;
      542: 
      543:       dest_vma = sec->output_section->vma + sec->output_offset + sym_value;
      544: 
      545:       if (symndx < 0
      546: 	  || (unsigned long) symndx >= obj_raw_syment_count (input_bfd))
      547: 	continue;
      548: 
      549:       /* All the relocs handled below operate on 4 bytes.  */
      550:       if (input_section->size < rel->r_vaddr
      551: 	  || input_section->size - rel->r_vaddr < 4)
      552: 	{
      553: 	  _bfd_error_handler
      554: 	    /* xgettext: c-format */
      555: 	    (_("%pB: bad reloc address %#" PRIx64 " in section `%pA'"),
      556: 	     input_bfd, (uint64_t) rel->r_vaddr, input_section);
      557: 	  continue;
      558: 	}
